<?php
namespace App\Console\Commands; use Illuminate\Console\Command; use App\Models\Invoice; use App\Services\FonnteService;
class SendBillingReminders extends Command {protected $signature='billing:reminders {offset=0}';protected $description='Antrekan reminder WhatsApp berdasarkan offset hari';public function handle(FonnteService $wa):int{$offset=(int)$this->argument('offset');$day=now(config('billing.timezone'))->startOfDay()->addDays($offset);$n=0;Invoice::with('customer')->where('status','unpaid')->whereDate('due_date',$day->toDateString())->chunkById(100,function($items)use($wa,&$n){foreach($items as $i){if(!$i->customer->phone)continue;$msg="Halo {$i->customer->name}, tagihan {$i->invoice_number} sebesar Rp ".number_format($i->total,0,',','.')." jatuh tempo pada {$i->due_date->format('d-m-Y')}. Pembayaran: ".($i->payment_url?:url('/pay/'.$i->public_token));$wa->queue($i->customer_id,$i->customer->phone,$msg,'billing_reminder',['name'=>$i->customer->name,'invoice_number'=>$i->invoice_number,'amount'=>number_format($i->total,0,',','.'),'due_date'=>$i->due_date->format('d-m-Y'),'payment_url'=>$i->payment_url?:url('/pay/'.$i->public_token)]);$n++;}});$this->info("{$n} reminder masuk antrean.");return self::SUCCESS;}}
